insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('adultos-mayores-y-servicios-de-salud-digitales','salud',array['educacion']::text[],'Adultos mayores y servicios de salud digitales','Descubre qué dificulta que una persona mayor use una cita en línea, un portal de resultados o una aplicación de salud, y cómo se podría hacer más fácil.','Análisis','~20 h',20,array['Accesibilidad','Adultos mayores','Servicios digitales']::text[],array['investigar','resolver']::text[],'ficticios',NULL,'ingenieria de sistemas ingenieria de software educacion psicologia trabajo social medicina diseno grafico comunicaciones observacion de usuarios. diseno de servicios accesibles. comunicacion clara. empatia. herramientas de maquetas. documento o presentacion. cuaderno de observaciones.',$f36sld${"id": "adultos-mayores-y-servicios-de-salud-digitales", "area": "salud", "areas2": ["educacion"], "titulo": "Adultos mayores y servicios de salud digitales", "resumen": "Descubre qué dificulta que una persona mayor use una cita en línea, un portal de resultados o una aplicación de salud, y cómo se podría hacer más fácil.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Accesibilidad", "Adultos mayores", "Servicios digitales"], "intencion": ["investigar", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Educación", "Psicología", "Trabajo Social", "Medicina", "Diseño Gráfico", "Comunicaciones"], "problema": ["Cada vez más servicios de salud, como las citas, los resultados o las consultas, se piden desde el celular. Para muchas personas mayores eso significa depender de otra persona o dejar de atenderse.", "No es solo falta de habilidad: las letras pequeñas, los pasos confusos, las contraseñas olvidadas o el miedo a equivocarse hacen que usar el servicio sea más difícil de lo necesario."], "desarrollar": ["Elige un servicio digital de salud inventado o de ejemplo, por ejemplo la reserva de una cita en línea, y haz que algunas personas, con su permiso, intenten realizarla. Observa dónde se detienen y qué les confunde.", "Propón cambios al diseño y al proceso, como menos pasos, letras más grandes o una vía alternativa por llamada. El resultado puede ser un informe de lo observado con un prototipo mejorado."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara qué ayuda más: una guía impresa, una persona de apoyo o rediseñar el servicio."}, {"titulo": "Un paso más", "aporta": "piensa cómo apoyar a quienes no tienen celular ni internet."}, {"titulo": "Otro formato", "aporta": "elabora una guía de uso paso a paso con fotos del servicio de ejemplo."}], "objetivos": ["Observar cómo una persona mayor usa un servicio digital.", "Identificar dónde se confunde.", "Proponer cambios de diseño y alternativas.", "Probar la mejora."], "habilidades": ["Observación de usuarios.", "Diseño de servicios accesibles.", "Comunicación clara.", "Empatía."], "herramientas": ["Herramientas de maquetas.", "Documento o presentación.", "Cuaderno de observaciones."], "lineamientos": ["Trabaja con un servicio de ejemplo o inventado, y con personas que acepten participar; nunca uses sus datos reales de salud ni sus claves.", "Trata a las personas con respeto: el problema es el diseño del servicio, no su capacidad."], "otroSector": "La misma idea sirve para banca en línea, trámites del Estado, pagos de servicios o compras por internet."}$f36sld$::jsonb,36),
('una-campana-contra-la-automedicacion','salud',array['arte']::text[],'Una campaña contra la automedicación','Diseña una campaña que explique, sin asustar, por qué conviene consultar antes de tomar medicamentos por cuenta propia, y a quién acudir.','Plan','~20 h',20,array['Campañas','Prevención','Comunicación']::text[],array['crear','resolver']::text[],'ficticios',NULL,'comunicaciones diseno grafico medicina enfermeria psicologia administracion educacion derecho comunicacion persuasiva. diseno de campanas. investigacion de habitos. redaccion de mensajes. herramientas de diseno. documento o presentacion. fuentes oficiales de salud.',$f37sld${"id": "una-campana-contra-la-automedicacion", "area": "salud", "areas2": ["arte"], "titulo": "Una campaña contra la automedicación", "resumen": "Diseña una campaña que explique, sin asustar, por qué conviene consultar antes de tomar medicamentos por cuenta propia, y a quién acudir.", "tipo": "Plan", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Campañas", "Prevención", "Comunicación"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Comunicaciones", "Diseño Gráfico", "Medicina", "Enfermería", "Psicología", "Administración", "Educación", "Derecho"], "problema": ["Tomar algo «que siempre funciona», lo que sobró de la última vez o lo que recomendó un conocido es muy común, y muchas veces se hace con la mejor intención. Pero puede esconder una enfermedad, causar daño o interactuar con otro medicamento.", "Los mensajes del tipo «no te automediques» no explican por qué ni qué hacer cuando no se puede ir al médico, y por eso la gente no los sigue."], "desarrollar": ["Investiga con fuentes oficiales las razones por las que las personas se automedican, como costo, comodidad o desconfianza, y las que más preocupan a los servicios de salud. Diseña una campaña con un mensaje central, tres piezas y una alternativa realista para quien no puede atenderse de inmediato, como una farmacia o una línea de orientación.", "El resultado puede ser un plan de campaña con ejemplos de las piezas y cómo medir su efecto."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara cómo se perciben los mensajes de advertencia frente a los de apoyo."}, {"titulo": "Otro público", "aporta": "adapta la campaña para jóvenes, para madres o para personas mayores."}, {"titulo": "Un paso más", "aporta": "diseña una pequeña guía de qué preguntar en una farmacia."}], "objetivos": ["Entender por qué las personas se automedican.", "Definir un mensaje respetuoso y claro.", "Diseñar piezas de campaña.", "Plantear cómo medir su efecto."], "habilidades": ["Comunicación persuasiva.", "Diseño de campañas.", "Investigación de hábitos.", "Redacción de mensajes."], "herramientas": ["Herramientas de diseño.", "Documento o presentación.", "Fuentes oficiales de salud."], "lineamientos": ["No menciones medicamentos específicos con dosis ni digas qué tomar. La campaña orienta a consultar con un profesional, no recomienda ni descarta ningún tratamiento.", "Evita culpar o avergonzar a quienes lo hacen: muchas veces no tienen otra opción."], "otroSector": "La misma campaña sirve para otros hábitos con riesgos, como el uso de aplicaciones de préstamo, de conexiones eléctricas caseras o de compras en línea."}$f37sld$::jsonb,37),
('atencion-de-salud-sin-barrera-de-idioma','salud',array['sociedad']::text[],'Atención de salud sin barrera de idioma','Explora qué ocurre cuando una persona no habla bien el idioma predominante de su localidad al recibir atención, y cómo se podría hacer la comunicación más segura y respetuosa.','Análisis','~20 h',20,array['Inclusión','Idioma','Atención al paciente']::text[],array['investigar','resolver']::text[],'ficticios',NULL,'trabajo social medicina enfermeria psicologia educacion comunicaciones sociologia derecho comunicacion intercultural. diseno de materiales visuales. empatia. analisis de casos. herramientas de diseno. documento o presentacion. fuentes de organismos publicos y de comunidades.',$f38sld${"id": "atencion-de-salud-sin-barrera-de-idioma", "area": "salud", "areas2": ["sociedad"], "titulo": "Atención de salud sin barrera de idioma", "resumen": "Explora qué ocurre cuando una persona no habla bien el idioma predominante de su localidad al recibir atención, y cómo se podría hacer la comunicación más segura y respetuosa.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Inclusión", "Idioma", "Atención al paciente"], "intencion": ["investigar", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Trabajo Social", "Medicina", "Enfermería", "Psicología", "Educación", "Comunicaciones", "Sociología", "Derecho"], "problema": ["En muchas zonas conviven varias lenguas, y migrantes, personas sordas o hablantes de lenguas originarias necesitan atenderse en un idioma que no dominan. Un malentendido puede significar un tratamiento mal explicado o un síntoma no comunicado.", "La solución rara vez es solo traducir: hay que cuidar la confianza, los gestos, los términos de salud y el trato."], "desarrollar": ["Describe, con un caso inventado, una consulta en la que la persona y el personal no comparten idioma, y marca dónde se pierde información. Reúne ideas de buenas prácticas de fuentes públicas: materiales en varias lenguas, intérpretes, tarjetas con imágenes.", "Diseña una pequeña propuesta, como un conjunto de tarjetas con imágenes para preguntas básicas. El resultado puede ser un prototipo de material más una nota de recomendaciones."], "ampliaciones": [{"titulo": "Otro público", "aporta": "adapta la propuesta para personas sordas o con discapacidad auditiva."}, {"titulo": "Otra mirada", "aporta": "investiga qué apoyos existen en tu zona y qué tan conocidos son."}, {"titulo": "Un paso más", "aporta": "incorpora cómo verificar que la persona realmente entendió."}], "objetivos": ["Describir qué se pierde en una consulta sin idioma común.", "Reunir buenas prácticas de comunicación.", "Diseñar un material de apoyo.", "Plantear cómo comprobar que se entendió."], "habilidades": ["Comunicación intercultural.", "Diseño de materiales visuales.", "Empatía.", "Análisis de casos."], "herramientas": ["Herramientas de diseño.", "Documento o presentación.", "Fuentes de organismos públicos y de comunidades."], "lineamientos": ["Si usas términos o materiales en otra lengua, consúltalos con hablantes de esa lengua para evitar errores. No uses traductores automáticos como única fuente en temas de salud.", "Respeta la cultura y no reduzcas a una comunidad a un solo estereotipo."], "otroSector": "La misma propuesta sirve para trámites, comercios, turismo o atención al cliente."}$f38sld$::jsonb,38),
('por-que-se-retrasa-la-atencion-de-una-emergencia','salud',array['ciudades']::text[],'¿Por qué se retrasa la atención de una emergencia?','Reconstruye las etapas desde que alguien pide ayuda hasta que recibe atención, y descubre dónde se pierden minutos y por qué.','Análisis','~25 h',25,array['Emergencias','Procesos','Datos']::text[],array['investigar','resolver']::text[],'publicos',NULL,'ingenieria industrial ingenieria civil ingenieria de sistemas estadistica medicina enfermeria administracion trabajo social analisis de procesos. analisis de datos. pensamiento sistemico. comunicacion visual. hoja de calculo. diagramas de flujo. portales de datos publicos.',$f39sld${"id": "por-que-se-retrasa-la-atencion-de-una-emergencia", "area": "salud", "areas2": ["ciudades"], "titulo": "¿Por qué se retrasa la atención de una emergencia?", "resumen": "Reconstruye las etapas desde que alguien pide ayuda hasta que recibe atención, y descubre dónde se pierden minutos y por qué.", "tipo": "Análisis", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Emergencias", "Procesos", "Datos"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Ingeniería Industrial", "Ingeniería Civil", "Ingeniería de Sistemas", "Estadística", "Medicina", "Enfermería", "Administración", "Trabajo Social"], "problema": ["En una emergencia cada minuto cuenta, y la atención depende de una cadena larga: avisar, ubicar, enviar ayuda, llegar, atender y trasladar. Un solo eslabón lento retrasa todo.", "Los retrasos tienen causas distintas: direcciones difíciles de encontrar, tráfico, falta de camas o de personal, llamadas mal derivadas. Sin separarlas, no se sabe qué mejorar."], "desarrollar": ["Divide el recorrido de una emergencia en etapas y busca información pública sobre el tiempo de cada una. Si no la hay, construye un caso con datos ficticios y marca dónde se acumulan los retrasos.", "Identifica los factores que los provocan y propón tres mejoras posibles. El resultado puede ser una línea de tiempo con tiempos por etapa y una lista de factores con propuestas."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara una zona urbana y una rural: qué cambia entre ellas."}, {"titulo": "Un paso más", "aporta": "simula cuánto tiempo se ganaría si se mejora una etapa específica."}, {"titulo": "Otro formato", "aporta": "crea una infografía que explique el recorrido de una emergencia a quien no lo conoce."}], "objetivos": ["Dividir la atención de una emergencia en etapas.", "Reunir información o datos ficticios por etapa.", "Identificar factores de retraso.", "Proponer mejoras."], "habilidades": ["Análisis de procesos.", "Análisis de datos.", "Pensamiento sistémico.", "Comunicación visual."], "herramientas": ["Hoja de cálculo.", "Diagramas de flujo.", "Portales de datos públicos."], "lineamientos": ["Usa información pública o inventada; no revises casos reales ni historias de personas. No culpes al personal de salud: los retrasos suelen venir del sistema.", "No des indicaciones sobre cómo actuar en una emergencia: remite siempre a la línea oficial de emergencias."], "otroSector": "El mismo análisis sirve para tiempos de respuesta de bomberos, de reparaciones, de entregas o de atención al cliente."}$f39sld$::jsonb,39),
('cuidar-a-quien-cuida-el-bienestar-de-quienes-atienden-a-un-enfermo','salud',array['sociedad']::text[],'Cuidar a quien cuida: el bienestar de quienes atienden a un enfermo','Descubre qué dificultades enfrentan quienes cuidan a un familiar enfermo, como el cansancio, el dinero o el aislamiento, y qué apoyos podrían aliviarlas.','Investigación','~20 h',20,array['Cuidadores','Bienestar','Familia']::text[],array['investigar','resolver']::text[],'publicos',NULL,'trabajo social psicologia enfermeria medicina sociologia educacion administracion comunicaciones investigacion social. empatia y escucha. diseno de apoyos. redaccion de informes. documento o presentacion. hoja de calculo. fuentes de organismos publicos.',$f40sld${"id": "cuidar-a-quien-cuida-el-bienestar-de-quienes-atienden-a-un-enfermo", "area": "salud", "areas2": ["sociedad"], "titulo": "Cuidar a quien cuida: el bienestar de quienes atienden a un enfermo", "resumen": "Descubre qué dificultades enfrentan quienes cuidan a un familiar enfermo, como el cansancio, el dinero o el aislamiento, y qué apoyos podrían aliviarlas.", "tipo": "Investigación", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Cuidadores", "Bienestar", "Familia"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Trabajo Social", "Psicología", "Enfermería", "Medicina", "Sociología", "Educación", "Administración", "Comunicaciones"], "problema": ["En muchas familias alguien asume el cuidado de una persona enferma o mayor, a menudo una mujer, y lo hace sin descanso, sin pago y sin preparación. Cuidar cansa, aísla y suele hacer descuidar la propia salud.", "Esa persona casi nunca aparece en los servicios de salud: se atiende al paciente, pero no a quien lo cuida."], "desarrollar": ["Reúne información pública sobre las dificultades de los cuidadores y agrúpalas en físicas, emocionales, económicas y sociales. Construye dos o tres perfiles inventados y para cada uno propón qué apoyo sería realista, como descansos, información o grupos de apoyo.", "El resultado puede ser un informe breve con los perfiles y un conjunto de recomendaciones para servicios de salud o para una comunidad."], "ampliaciones": [{"titulo": "Otro público", "aporta": "adapta el análisis a jóvenes que cuidan a sus abuelos o a hermanos."}, {"titulo": "Otro formato", "aporta": "crea una guía de autocuidado y recursos para quien cuida."}, {"titulo": "Un paso más", "aporta": "calcula cuánto trabajo no pagado representa el cuidado en una familia."}], "objetivos": ["Reunir las dificultades de quienes cuidan.", "Construir perfiles de cuidadores.", "Proponer apoyos realistas.", "Presentar los hallazgos con empatía."], "habilidades": ["Investigación social.", "Empatía y escucha.", "Diseño de apoyos.", "Redacción de informes."], "herramientas": ["Documento o presentación.", "Hoja de cálculo.", "Fuentes de organismos públicos."], "lineamientos": ["Trabaja con perfiles inventados y datos públicos; no pidas a cuidadores reales que cuenten su situación. Evita presentar el cuidado como una carga o como un sacrificio heroico.", "No des consejos médicos sobre cómo cuidar a un enfermo: remite siempre a profesionales de salud."], "otroSector": "El mismo análisis sirve para estudiar el trabajo no remunerado en el hogar, el voluntariado o el cuidado de niños."}$f40sld$::jsonb,40),
('guia-para-acompanar-a-un-familiar-hospitalizado','salud',array['sociedad']::text[],'Guía para acompañar a un familiar hospitalizado','Elabora una guía práctica para quien acompaña a un familiar en el hospital: qué llevar, qué preguntar, cómo organizarse y cómo cuidarse.','Guía','~15 h',15,array['Familia','Hospitalización','Comunicación']::text[],array['crear','resolver']::text[],'ficticios',NULL,'enfermeria trabajo social psicologia medicina comunicaciones educacion diseno grafico administracion redaccion de guias. comunicacion empatica. busqueda de informacion confiable. diseno de materiales. documento o presentacion. herramientas de diseno. plantillas de listas de verificacion.',$f41sld${"id": "guia-para-acompanar-a-un-familiar-hospitalizado", "area": "salud", "areas2": ["sociedad"], "titulo": "Guía para acompañar a un familiar hospitalizado", "resumen": "Elabora una guía práctica para quien acompaña a un familiar en el hospital: qué llevar, qué preguntar, cómo organizarse y cómo cuidarse.", "tipo": "Guía", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Familia", "Hospitalización", "Comunicación"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Enfermería", "Trabajo Social", "Psicología", "Medicina", "Comunicaciones", "Educación", "Diseño Gráfico", "Administración"], "problema": ["Cuando alguien de la familia se hospitaliza, quienes lo acompañan se enfrentan a un mundo desconocido: horarios de visita, trámites, términos que no entienden y decisiones rápidas. Muchos aprenden sobre la marcha y con mucho estrés.", "Las orientaciones que ofrecen los servicios suelen ser breves y técnicas, y casi no hablan de las necesidades de la familia, como comer, descansar o turnarse."], "desarrollar": ["Define las situaciones más comunes de un acompañante, como el primer día, las preguntas al equipo, los trámites, la noche y el alta. Para cada una escribe consejos prácticos tomados de fuentes confiables y entrevistas inventadas o testimonios públicos.", "Preséntala en un formato fácil de leer en una sala de espera: una guía de pocas páginas o una serie de tarjetas. Pruébala con alguien que no conozca el tema."], "ampliaciones": [{"titulo": "Otro público", "aporta": "adapta la guía para quien acompaña a un niño o a un adulto mayor."}, {"titulo": "Otro formato", "aporta": "conviértela en una lista de verificación para imprimir y llevar en el bolso."}, {"titulo": "Una prueba", "aporta": "pide a alguien que la lea y diga qué preguntas aún le quedan."}], "objetivos": ["Identificar las situaciones más difíciles de un acompañante.", "Reunir consejos prácticos de fuentes confiables.", "Redactar una guía clara.", "Probar que sea fácil de entender."], "habilidades": ["Redacción de guías.", "Comunicación empática.", "Búsqueda de información confiable.", "Diseño de materiales."], "herramientas": ["Documento o presentación.", "Herramientas de diseño.", "Plantillas de listas de verificación."], "lineamientos": ["No incluyas información médica específica ni indicaciones de tratamiento: la guía trata de organización y acompañamiento. Usa casos inventados.", "Indica que las dudas sobre la salud del paciente se resuelven siempre con el equipo de salud."], "otroSector": "La misma guía sirve para acompañar un trámite largo, una mudanza, un viaje de estudio o un proceso judicial."}$f41sld$::jsonb,41),
('despues-del-alta-que-pasa-cuando-el-paciente-vuelve-a-casa','salud',array['industria']::text[],'Después del alta: ¿qué pasa cuando el paciente vuelve a casa?','Descubre qué necesita una persona al salir de un servicio de salud para seguir su recuperación en casa, y cómo se podría hacer ese paso más seguro y claro.','Análisis','~20 h',20,array['Continuidad','Atención al paciente','Procesos']::text[],array['investigar','resolver']::text[],'ficticios',NULL,'enfermeria medicina trabajo social ingenieria industrial administracion psicologia ingenieria de sistemas comunicaciones mapeo de procesos. diseno de servicios. comunicacion clara. empatia. diagramas de flujo. documento o presentacion. hoja de calculo.',$f42sld${"id": "despues-del-alta-que-pasa-cuando-el-paciente-vuelve-a-casa", "area": "salud", "areas2": ["industria"], "titulo": "Después del alta: ¿qué pasa cuando el paciente vuelve a casa?", "resumen": "Descubre qué necesita una persona al salir de un servicio de salud para seguir su recuperación en casa, y cómo se podría hacer ese paso más seguro y claro.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Continuidad", "Atención al paciente", "Procesos"], "intencion": ["investigar", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Enfermería", "Medicina", "Trabajo Social", "Ingeniería Industrial", "Administración", "Psicología", "Ingeniería de Sistemas", "Comunicaciones"], "problema": ["Salir del hospital o del consultorio no significa que el cuidado terminó: empieza otra etapa con citas de control, medicamentos, cuidados en casa y señales de alerta. Muchas personas vuelven sin entender qué sigue o a quién llamar.", "Cuando esa etapa falla, aparecen reingresos, complicaciones o tratamientos que se abandonan. Nadie suele estar a cargo de acompañar ese tramo."], "desarrollar": ["Con un caso inventado, describe qué ocurre desde el momento del alta hasta la primera semana en casa. Lista qué información, materiales y apoyos necesitaría esa persona y quién debería dárselos.", "Diseña una propuesta simple, como una hoja de alta clara, una llamada de seguimiento o una lista de qué hacer y a quién llamar. El resultado puede ser un recorrido con puntos críticos y un modelo de la hoja de alta."], "ampliaciones": [{"titulo": "Otro público", "aporta": "adapta la propuesta para adultos mayores o para quien vive solo."}, {"titulo": "Otra mirada", "aporta": "estima qué problemas se evitarían si una pregunta específica se hiciera antes del alta."}, {"titulo": "Un paso más", "aporta": "incorpora cómo involucrar a la persona que cuidará al paciente en casa."}], "objetivos": ["Describir el paso del servicio de salud al hogar.", "Identificar lo que necesita la persona en esa etapa.", "Proponer materiales y apoyos concretos.", "Presentar el resultado con un recorrido claro."], "habilidades": ["Mapeo de procesos.", "Diseño de servicios.", "Comunicación clara.", "Empatía."], "herramientas": ["Diagramas de flujo.", "Documento o presentación.", "Hoja de cálculo."], "lineamientos": ["Trabaja con un caso inventado; no uses historias clínicas reales ni indicaciones médicas específicas. Describe lo que falta sin culpar al personal.", "La hoja de alta que diseñes es un modelo ilustrativo: no sustituye las instrucciones que da un profesional de la salud."], "otroSector": "El mismo análisis sirve para la entrega de un trabajo, el fin de un proyecto o el cierre de un servicio técnico."}$f42sld$::jsonb,42),
('como-prepararte-para-una-consulta-medica','salud',array['educacion']::text[],'Cómo prepararte para una consulta médica','Crea una guía breve para llegar a una consulta sabiendo qué contar, qué preguntar y qué llevar, y así aprovechar mejor el poco tiempo disponible.','Guía','~8 h',8,array['Comunicación','Atención al paciente']::text[],array['resolver','crear']::text[],'ficticios',NULL,'medicina enfermeria psicologia educacion comunicaciones diseno grafico trabajo social administracion redaccion clara. diseno de materiales. comunicacion en salud. empatia. documento o presentacion. herramientas de diseno. plantillas imprimibles.',$f43sld${"id": "como-prepararte-para-una-consulta-medica", "area": "salud", "areas2": ["educacion"], "titulo": "Cómo prepararte para una consulta médica", "resumen": "Crea una guía breve para llegar a una consulta sabiendo qué contar, qué preguntar y qué llevar, y así aprovechar mejor el poco tiempo disponible.", "tipo": "Guía", "tiempo": "~8 h", "horas": 8, "etiquetas": ["Comunicación", "Atención al paciente"], "intencion": ["resolver", "crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Medicina", "Enfermería", "Psicología", "Educación", "Comunicaciones", "Diseño Gráfico", "Trabajo Social", "Administración"], "problema": ["Las consultas son cortas y a veces intimidantes. Muchas personas salen pensando «se me olvidó preguntar» o «no supe explicar bien», y la información importante se pierde.", "Una consulta bien preparada ayuda tanto a quien se atiende como a quien atiende: el profesional entiende más rápido, y la persona se va con menos dudas."], "desarrollar": ["Define qué conviene preparar antes de una consulta: cómo describir lo que se siente, qué datos reunir, qué preguntas hacer y qué llevar. Escribe ejemplos con casos inventados.", "Arma una guía de una página o una tarjeta con una pequeña lista de verificación, y pruébala con alguien que tenga una cita próxima y quiera usarla."], "ampliaciones": [{"titulo": "Otro público", "aporta": "adapta la guía para llevar a un niño, a un adulto mayor o a un familiar."}, {"titulo": "Otro formato", "aporta": "conviértela en una plantilla para anotar durante la consulta."}, {"titulo": "Una prueba", "aporta": "compara qué información se recuerda con y sin la guía."}], "objetivos": ["Identificar qué conviene preparar antes de una consulta.", "Escribir preguntas y ejemplos claros.", "Elaborar una guía o tarjeta fácil de usar.", "Probarla con alguien."], "habilidades": ["Redacción clara.", "Diseño de materiales.", "Comunicación en salud.", "Empatía."], "herramientas": ["Documento o presentación.", "Herramientas de diseño.", "Plantillas imprimibles."], "lineamientos": ["La guía no debe hacer diagnósticos ni sugerir qué debe decir el profesional. Usa casos inventados en los ejemplos.", "Indica que la guía no sustituye lo que el profesional pregunte: es solo un apoyo para organizar las ideas."], "otroSector": "La misma guía sirve para prepararse a una entrevista de trabajo, una reunión importante o un trámite."}$f43sld$::jsonb,43),
('como-decide-una-persona-sobre-su-salud-y-en-quien-confia','salud',array['sociedad']::text[],'¿Cómo decide una persona sobre su salud y en quién confía?','Explora cómo las personas deciden qué hacer ante un problema de salud y qué hace que confíen en una recomendación, un profesional o una fuente de información.','Investigación','~20 h',20,array['Decisiones','Confianza','Comunicación']::text[],array['investigar','otro-sector']::text[],'publicos',NULL,'psicologia sociologia comunicaciones medicina enfermeria economia educacion trabajo social lectura de estudios. analisis del comportamiento. sintesis y redaccion. pensamiento critico. documento o presentacion. formularios en linea. buscadores academicos.',$f44sld${"id": "como-decide-una-persona-sobre-su-salud-y-en-quien-confia", "area": "salud", "areas2": ["sociedad"], "titulo": "¿Cómo decide una persona sobre su salud y en quién confía?", "resumen": "Explora cómo las personas deciden qué hacer ante un problema de salud y qué hace que confíen en una recomendación, un profesional o una fuente de información.", "tipo": "Investigación", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Decisiones", "Confianza", "Comunicación"], "intencion": ["investigar", "otro-sector"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Psicología", "Sociología", "Comunicaciones", "Medicina", "Enfermería", "Economía", "Educación", "Trabajo Social"], "problema": ["Ante un síntoma, una vacuna o un tratamiento, las personas deciden con una mezcla de información, experiencias previas, opinión de la familia, costos, emociones y confianza. No siempre siguen lo que dice la evidencia, y no siempre es por ignorancia.", "Entender cómo se decide y en quién se confía es clave para comunicar mejor, pero casi nunca se estudia con calma."], "desarrollar": ["Reúne estudios públicos sobre toma de decisiones en salud y confianza, y extrae los factores que más se mencionan: experiencia previa, cercanía, claridad, autoridad, similitud con uno mismo. Crea tres o cuatro situaciones inventadas y explica con esos factores qué haría cada persona.", "El resultado puede ser un informe con un mapa de factores y ejemplos, y una nota sobre qué implica para quien comunica."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara cómo influyen la familia, los medios y las redes en decisiones distintas."}, {"titulo": "Otro formato", "aporta": "diseña una pequeña encuesta anónima para explorar el tema con compañeros."}, {"titulo": "Un paso más", "aporta": "propón cómo un servicio de salud podría construir confianza con una comunidad."}], "objetivos": ["Reunir factores que influyen en las decisiones de salud.", "Explicar por qué se confía en unas fuentes y no en otras.", "Construir situaciones de ejemplo.", "Resumir lo que implica para quien comunica."], "habilidades": ["Lectura de estudios.", "Análisis del comportamiento.", "Síntesis y redacción.", "Pensamiento crítico."], "herramientas": ["Documento o presentación.", "Formularios en línea.", "Buscadores académicos."], "lineamientos": ["Si haces una encuesta, que sea anónima y voluntaria, sin preguntas sobre enfermedades personales. No ridiculices las decisiones de nadie: tu objetivo es comprenderlas.", "No indiques qué decisión de salud es correcta; remite siempre a fuentes oficiales."], "otroSector": "El mismo análisis sirve para entender cómo se decide qué comprar, a quién votar o qué creer sobre un tema."}$f44sld$::jsonb,44),
('pausas-activas-para-estudiar-o-trabajar','salud',array['educacion']::text[],'Pausas activas para estudiar o trabajar','Diseña un programa de pausas breves que ayude a quienes pasan horas sentados a moverse y descansar la vista sin perder el ritmo de estudio o de trabajo.','Plan','~15 h',15,array['Bienestar','Pausas activas','Hábitos']::text[],array['crear','resolver']::text[],'ficticios',NULL,'educacion medicina enfermeria psicologia ingenieria industrial administracion diseno grafico trabajo social diseno de programas. observacion de rutinas. comunicacion clara. evaluacion sencilla. cronometro o recordatorios en el celular. herramientas para disenar tarjetas. hoja de calculo para seguimiento.',$f45sld${"id": "pausas-activas-para-estudiar-o-trabajar", "area": "salud", "areas2": ["educacion"], "titulo": "Pausas activas para estudiar o trabajar", "resumen": "Diseña un programa de pausas breves que ayude a quienes pasan horas sentados a moverse y descansar la vista sin perder el ritmo de estudio o de trabajo.", "tipo": "Plan", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Bienestar", "Pausas activas", "Hábitos"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Educación", "Medicina", "Enfermería", "Psicología", "Ingeniería Industrial", "Administración", "Diseño Gráfico", "Trabajo Social"], "problema": ["Estudiar o trabajar muchas horas seguidas cansa el cuerpo y la mente, pero casi nadie se levanta hasta que duele. Las pausas suelen verse como pérdida de tiempo, aunque ayudan a concentrarse mejor.", "Muchos programas de pausas activas fracasan porque exigen demasiado, no tienen en cuenta el lugar o nadie los recuerda."], "desarrollar": ["Elige un espacio, como una biblioteca, un salón o una oficina, y observa cómo se usan las horas. Diseña un programa de pausas de uno a cinco minutos, con movimientos sencillos, seguros y adecuados al lugar, y una forma de recordarlas.", "Pruébalo con un grupo pequeño durante unos días y anota qué hizo que se cumpliera o no. El resultado puede ser un plan con rutina, material y recordatorios."], "ampliaciones": [{"titulo": "Otro público", "aporta": "adapta las pausas para personas con movilidad reducida o para quienes trabajan de pie."}, {"titulo": "Otra mirada", "aporta": "compara pausas cortas frecuentes con pausas largas espaciadas en cuanto a cumplimiento."}, {"titulo": "Un paso más", "aporta": "crea una animación o una tarjeta que muestre los movimientos."}], "objetivos": ["Observar cómo se usa el tiempo en un espacio.", "Diseñar pausas breves, seguras y realistas.", "Plantear una forma de recordarlas.", "Probar el programa con un grupo."], "habilidades": ["Diseño de programas.", "Observación de rutinas.", "Comunicación clara.", "Evaluación sencilla."], "herramientas": ["Cronómetro o recordatorios en el celular.", "Herramientas para diseñar tarjetas.", "Hoja de cálculo para seguimiento."], "lineamientos": ["Los movimientos deben ser suaves y seguros; no propongas ejercicios exigentes ni los indiques como tratamiento de dolores o lesiones. Quien tenga molestias debe consultar a un profesional.", "Pide permiso antes de aplicar el programa en un lugar y que la participación sea voluntaria."], "otroSector": "El mismo diseño sirve para pausas de estudio, rutinas de limpieza, mantenimiento periódico o recordatorios de seguridad."}$f45sld$::jsonb,45),
('vivir-con-una-enfermedad-cronica-en-el-dia-a-dia','salud',array['sociedad']::text[],'Vivir con una enfermedad crónica en el día a día','Explora los retos prácticos de convivir con una condición que dura toda la vida, como horarios, costos, trabajo y apoyo, y qué ayudas podrían facilitarlo.','Investigación','~25 h',25,array['Enfermedades crónicas','Vida cotidiana','Apoyo']::text[],array['investigar','resolver']::text[],'publicos',NULL,'trabajo social psicologia enfermeria medicina sociologia administracion educacion diseno grafico investigacion social. empatia. mapeo de rutinas. redaccion de propuestas. documento o presentacion. hoja de calculo para costos y tiempos. fuentes publicas y de asociaciones de pacientes.',$f46sld${"id": "vivir-con-una-enfermedad-cronica-en-el-dia-a-dia", "area": "salud", "areas2": ["sociedad"], "titulo": "Vivir con una enfermedad crónica en el día a día", "resumen": "Explora los retos prácticos de convivir con una condición que dura toda la vida, como horarios, costos, trabajo y apoyo, y qué ayudas podrían facilitarlo.", "tipo": "Investigación", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Enfermedades crónicas", "Vida cotidiana", "Apoyo"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Trabajo Social", "Psicología", "Enfermería", "Medicina", "Sociología", "Administración", "Educación", "Diseño Gráfico"], "problema": ["Una enfermedad crónica no es solo un tema médico: obliga a organizar la vida alrededor de controles, medicamentos, comidas, cansancio y gastos. Afecta al trabajo, a los estudios, a las relaciones y a las ganas de seguir adelante.", "Desde afuera se ve la enfermedad; desde adentro, la parte más difícil suele ser sostener la rutina durante años."], "desarrollar": ["Revisa información pública y testimonios publicados con autorización sobre la vida con una condición crónica, y arma un mapa de la rutina de una persona inventada: horarios, costos, apoyos y dificultades de un día típico. Identifica dónde un cambio pequeño en el entorno, como horarios flexibles o información clara, haría una gran diferencia.", "El resultado puede ser un informe con el mapa del día y propuestas para servicios, empleadores o instituciones educativas."], "ampliaciones": [{"titulo": "Otro público", "aporta": "adapta el análisis a un estudiante universitario que vive con una condición crónica."}, {"titulo": "Otra mirada", "aporta": "calcula cuánto cuesta, entre dinero y tiempo, sostener la rutina durante un año."}, {"titulo": "Un paso más", "aporta": "diseña una guía de apoyo para compañeros o familiares."}], "objetivos": ["Describir un día típico de quien vive con una condición crónica.", "Identificar dificultades prácticas.", "Proponer ajustes en el entorno.", "Presentar los hallazgos con respeto."], "habilidades": ["Investigación social.", "Empatía.", "Mapeo de rutinas.", "Redacción de propuestas."], "herramientas": ["Documento o presentación.", "Hoja de cálculo para costos y tiempos.", "Fuentes públicas y de asociaciones de pacientes."], "lineamientos": ["Trabaja con información pública y personas inventadas; no pidas a nadie que cuente su diagnóstico. Si usas testimonios, que sean públicos y con autorización.", "No des recomendaciones de tratamiento ni compares condiciones: el enfoque es la vida cotidiana, no la clínica."], "otroSector": "El mismo análisis sirve para la vida con una discapacidad, con un trabajo por turnos o con responsabilidades de cuidado."}$f46sld$::jsonb,46),
('orientarse-en-un-centro-de-salud-los-pasos-de-una-atencion','salud',array['arte']::text[],'Orientarse en un centro de salud: los pasos de una atención','Diseña una forma de guiar a una persona dentro de un centro de salud, con mapas, colores o pasos sencillos, para que sepa dónde ir y qué sigue sin tener que preguntar a cada paso.','Prototipo','~20 h',20,array['Orientación','Señalización','Experiencia del paciente']::text[],array['crear','resolver']::text[],'ficticios',NULL,'diseno grafico arquitectura comunicaciones ingenieria industrial enfermeria medicina trabajo social psicologia diseno de informacion y senalizacion. diseno centrado en las personas. observacion. maquetacion visual. herramientas de diseno grafico. croquis o planos sencillos. papel y marcadores para maquetas.',$f47sld${"id": "orientarse-en-un-centro-de-salud-los-pasos-de-una-atencion", "area": "salud", "areas2": ["arte"], "titulo": "Orientarse en un centro de salud: los pasos de una atención", "resumen": "Diseña una forma de guiar a una persona dentro de un centro de salud, con mapas, colores o pasos sencillos, para que sepa dónde ir y qué sigue sin tener que preguntar a cada paso.", "tipo": "Prototipo", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Orientación", "Señalización", "Experiencia del paciente"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Diseño Gráfico", "Arquitectura", "Comunicaciones", "Ingeniería Industrial", "Enfermería", "Medicina", "Trabajo Social", "Psicología"], "problema": ["Llegar a un centro de salud puede ser confuso: letreros con siglas, pasillos parecidos y pasos que nadie explica, como admisión, caja, triaje o laboratorio. Muchas personas se pierden, hacen filas equivocadas o se asustan.", "La confusión es mayor cuando la persona ya llega con dolor, con prisa o con poca experiencia en este tipo de lugares."], "desarrollar": ["Elige un centro de salud inventado, con áreas como recepción, consulta, laboratorio y farmacia, y diseña cómo se orientaría una persona nueva: un mapa sencillo, una secuencia de pasos con colores y mensajes claros. Prueba el diseño con alguien que no conozca el lugar, y pídele que cuente cómo llegaría a cada punto.", "El resultado puede ser un conjunto de maquetas de señalización, un mapa y una guía de los pasos de la atención."], "ampliaciones": [{"titulo": "Otro público", "aporta": "adapta el diseño para personas con discapacidad visual o que no leen bien."}, {"titulo": "Otra mirada", "aporta": "compara una señalización por colores con una por números o símbolos."}, {"titulo": "Otro formato", "aporta": "diseña una versión digital o impresa de bolsillo que la persona pueda llevar."}], "objetivos": ["Describir los pasos de una atención típica.", "Diseñar mapas y señales claras.", "Probar el diseño con una persona nueva.", "Ajustarlo según lo que no entendió."], "habilidades": ["Diseño de información y señalización.", "Diseño centrado en las personas.", "Observación.", "Maquetación visual."], "herramientas": ["Herramientas de diseño gráfico.", "Croquis o planos sencillos.", "Papel y marcadores para maquetas."], "lineamientos": ["Trabaja con un centro de salud inventado: no fotografíes ni intervengas en un establecimiento real sin autorización. Los colores y símbolos deben ser accesibles a quienes no distinguen bien los colores.", "No uses logotipos ni nombres de servicios reales."], "otroSector": "El mismo diseño sirve para orientar en una universidad, un aeropuerto, un museo, un mercado o una feria."}$f47sld$::jsonb,47),
('como-llega-una-vacuna-hasta-un-pueblo-lejano','salud',array['industria','ciudades']::text[],'¿Cómo llega una vacuna hasta un pueblo lejano?','Sigue el viaje de una vacuna desde su almacén hasta un pueblo alejado, y descubre qué cuidados exige y qué pasaría si alguno de los pasos falla.','Simulación','~30 h',30,array['Logística','Cadena de frío','Simulación']::text[],array['investigar','resolver']::text[],'ficticios',NULL,'ingenieria industrial ingenieria civil ingenieria de sistemas administracion estadistica medicina enfermeria ingenieria ambiental logistica y cadena de suministro. gestion de riesgos. modelamiento basico. analisis de datos. hoja de calculo. mapas en linea. diagramas de flujo.',$f48sld${"id": "como-llega-una-vacuna-hasta-un-pueblo-lejano", "area": "salud", "areas2": ["industria", "ciudades"], "titulo": "¿Cómo llega una vacuna hasta un pueblo lejano?", "resumen": "Sigue el viaje de una vacuna desde su almacén hasta un pueblo alejado, y descubre qué cuidados exige y qué pasaría si alguno de los pasos falla.", "tipo": "Simulación", "tiempo": "~30 h", "horas": 30, "etiquetas": ["Logística", "Cadena de frío", "Simulación"], "intencion": ["investigar", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Ingeniería Industrial", "Ingeniería Civil", "Ingeniería de Sistemas", "Administración", "Estadística", "Medicina", "Enfermería", "Ingeniería Ambiental"], "problema": ["Algunas vacunas y medicamentos deben mantenerse frescos durante todo el viaje. Si se rompe esa cadena, pierden su efecto, aunque nadie lo note. Llegar a un pueblo lejano, con caminos difíciles y electricidad intermitente, vuelve el reto aún mayor.", "Casi nadie ve esa parte del sistema de salud, pero de ella depende que lo que llega sea seguro."], "desarrollar": ["Con datos inventados, dibuja la ruta de una caja de vacunas desde un almacén central hasta un pueblo, con paradas, tiempos, temperatura y quién se hace cargo en cada tramo. Imagina qué ocurre si un vehículo se demora, si hay un corte de energía o si el hielo se acaba.", "Simula en una hoja de cálculo cuánto tiempo se podría mantener el frío y propón medidas para reducir los riesgos. El resultado puede ser un mapa de ruta con una simulación sencilla y recomendaciones."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara dos rutas distintas, una más corta pero difícil y otra más larga pero segura."}, {"titulo": "Un paso más", "aporta": "diseña cómo registrar la temperatura y quién debe avisar si algo sale mal."}, {"titulo": "Otro formato", "aporta": "convierte el modelo en una herramienta que calcule cuánto aguanta el frío una caja según el clima."}], "objetivos": ["Describir la ruta de un producto sensible a la temperatura.", "Identificar los riesgos de cada tramo.", "Simular escenarios de falla.", "Proponer medidas para reducir riesgos."], "habilidades": ["Logística y cadena de suministro.", "Gestión de riesgos.", "Modelamiento básico.", "Análisis de datos."], "herramientas": ["Hoja de cálculo.", "Mapas en línea.", "Diagramas de flujo."], "lineamientos": ["Usa datos inventados y una ruta ficticia; no es una evaluación de ningún servicio real. No indiques temperaturas de conservación de productos específicos: esos datos los fijan las autoridades de salud.", "Aclara que es un ejercicio de logística y que ningún cambio en la cadena real debe hacerse sin personal autorizado."], "otroSector": "El mismo modelo sirve para el transporte de alimentos frescos, flores, productos químicos o equipos delicados."}$f48sld$::jsonb,48),
('que-tan-facil-es-confundir-dos-medicamentos','salud',array['arte']::text[],'¿Qué tan fácil es confundir dos medicamentos?','Analiza cómo los nombres y los envases parecidos pueden llevar a una confusión, y propone cómo diseñarlos para reducir errores.','Análisis','~15 h',15,array['Seguridad del paciente','Diseño de información','Prevención']::text[],array['investigar','resolver']::text[],'ficticios',NULL,'diseno grafico comunicaciones medicina enfermeria ingenieria de sistemas ingenieria industrial psicologia trabajo social diseno de informacion. pruebas con usuarios. analisis de errores. comunicacion visual. herramientas de diseno grafico. hoja de calculo. papel y marcadores para las maquetas.',$f49sld${"id": "que-tan-facil-es-confundir-dos-medicamentos", "area": "salud", "areas2": ["arte"], "titulo": "¿Qué tan fácil es confundir dos medicamentos?", "resumen": "Analiza cómo los nombres y los envases parecidos pueden llevar a una confusión, y propone cómo diseñarlos para reducir errores.", "tipo": "Análisis", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Seguridad del paciente", "Diseño de información", "Prevención"], "intencion": ["investigar", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Diseño Gráfico", "Comunicaciones", "Medicina", "Enfermería", "Ingeniería de Sistemas", "Ingeniería Industrial", "Psicología", "Trabajo Social"], "problema": ["Muchos medicamentos tienen nombres que suenan casi igual, cajas del mismo color o letras diminutas. En una farmacia, en un botiquín o en una prisa, es fácil tomar uno por otro. Estos errores están entre los más estudiados en seguridad del paciente.", "Parte del problema está en cómo se diseñan los nombres y los envases, y no en las personas que se equivocan."], "desarrollar": ["Con medicamentos inventados, crea cinco o seis pares de nombres y envases parecidos, y pide a algunas personas que los distingan con poco tiempo. Anota qué errores cometen y qué elementos confunden más: el color, la tipografía, la forma o el sonido del nombre.", "A partir de eso, propón cómo debería ser un envase que reduzca la confusión. El resultado puede ser un informe breve con ejemplos y un rediseño de uno de los pares."], "ampliaciones": [{"titulo": "Otro público", "aporta": "prueba con personas mayores o con quienes tienen problemas de visión."}, {"titulo": "Otra mirada", "aporta": "investiga qué medidas se aplican en el mundo para evitar este tipo de errores."}, {"titulo": "Un paso más", "aporta": "diseña una etiqueta o un organizador casero que ayude a no confundir dos medicamentos."}], "objetivos": ["Identificar qué elementos provocan confusión.", "Probar con personas qué tan fácil se confunden.", "Proponer rediseños.", "Explicar qué cambio reduce más los errores."], "habilidades": ["Diseño de información.", "Pruebas con usuarios.", "Análisis de errores.", "Comunicación visual."], "herramientas": ["Herramientas de diseño gráfico.", "Hoja de cálculo.", "Papel y marcadores para las maquetas."], "lineamientos": ["Usa únicamente nombres y envases inventados: nunca medicamentos reales ni sus dosis. Las pruebas son de reconocimiento visual, no de uso.", "No indiques cómo se debe tomar ningún medicamento; remite a un profesional de la salud."], "otroSector": "El mismo análisis sirve para etiquetas de productos de limpieza, de alimentos, de cables o de repuestos."}$f49sld$::jsonb,49),
('donde-me-atiendo-sis-essalud-minsa-o-una-clinica','salud',array['derecho','sociedad']::text[],'¿Dónde me atiendo? SIS, EsSalud, Minsa o una clínica','Elabora una guía para que una persona entienda qué opciones de atención tiene en el Perú según su situación, y cómo empezar en cada una.','Guía','~15 h',15,array['Sistema de salud','Derechos','Orientación']::text[],array['resolver','crear']::text[],'publicos',NULL,'derecho trabajo social comunicaciones administracion medicina enfermeria sociologia ingenieria de sistemas lectura de informacion oficial. diseno de guias de decision. redaccion en lenguaje simple. verificacion de datos. diagramas de flujo. documento o presentacion. portales oficiales de las instituciones de salud.',$f50sld${"id": "donde-me-atiendo-sis-essalud-minsa-o-una-clinica", "area": "salud", "areas2": ["derecho", "sociedad"], "titulo": "¿Dónde me atiendo? SIS, EsSalud, Minsa o una clínica", "resumen": "Elabora una guía para que una persona entienda qué opciones de atención tiene en el Perú según su situación, y cómo empezar en cada una.", "tipo": "Guía", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Sistema de salud", "Derechos", "Orientación"], "intencion": ["resolver", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Derecho", "Trabajo Social", "Comunicaciones", "Administración", "Medicina", "Enfermería", "Sociología", "Ingeniería de Sistemas"], "problema": ["En el Perú conviven distintos tipos de servicios y de seguros: el Seguro Integral de Salud, EsSalud, los establecimientos del Ministerio de Salud, las clínicas y otras opciones. Para quien no está familiarizado, es un laberinto: ¿a cuál me corresponde?, ¿qué cubre?, ¿cómo me afilio?", "Cuando la persona no lo sabe, posterga la atención, paga de más o va al lugar equivocado."], "desarrollar": ["Revisa los portales oficiales y organiza la información en una guía de decisión: preguntas sencillas, como si trabajas, si eres estudiante o si no tienes seguro, que te lleven a las opciones posibles. Para cada opción resume cómo se accede, qué se necesita y dónde consultar.", "Verifica cada dato en la fuente oficial, indica la fecha de revisión y presenta el resultado como un diagrama de preguntas o una guía de pocas páginas."], "ampliaciones": [{"titulo": "Otro público", "aporta": "adapta la guía para estudiantes universitarios, para migrantes o para trabajadores independientes."}, {"titulo": "Otro formato", "aporta": "conviértela en un cuestionario interactivo sencillo."}, {"titulo": "Una prueba", "aporta": "pide a alguien que la use con un caso inventado y anota dónde se confunde."}], "objetivos": ["Reunir información oficial sobre las opciones de atención.", "Organizarla en una guía de decisión.", "Verificar cada dato con su fuente.", "Probar que sea fácil de usar."], "habilidades": ["Lectura de información oficial.", "Diseño de guías de decisión.", "Redacción en lenguaje simple.", "Verificación de datos."], "herramientas": ["Diagramas de flujo.", "Documento o presentación.", "Portales oficiales de las instituciones de salud."], "lineamientos": ["La información cambia: cita siempre la fuente y la fecha, y avisa que la guía es orientativa y no reemplaza la consulta en las páginas oficiales. No des asesoría legal.", "No recomiendes un servicio sobre otro; describe las opciones y sus requisitos."], "otroSector": "La misma guía sirve para orientar en trámites, becas, seguros, pensiones o servicios municipales."}$f50sld$::jsonb,50),
('lo-que-dicen-los-numeros-de-salud-de-tu-region','salud',array['tecnologia','ciencias']::text[],'Lo que dicen los números de salud de tu región','Convierte las estadísticas públicas de salud de tu región en algo que cualquiera pueda entender, y descubre qué cuentan los números y qué esconden.','Análisis','~25 h',25,array['Datos abiertos','Salud pública','Visualización']::text[],array['investigar','crear']::text[],'publicos',NULL,'estadistica ingenieria de sistemas ingenieria de software medicina enfermeria economia comunicaciones diseno grafico analisis de datos. visualizacion de informacion. lectura critica de estadisticas. comunicacion de resultados. hoja de calculo o herramienta de analisis de datos. portales de datos abiertos. herramientas para hacer graficos.',$f51sld${"id": "lo-que-dicen-los-numeros-de-salud-de-tu-region", "area": "salud", "areas2": ["tecnologia", "ciencias"], "titulo": "Lo que dicen los números de salud de tu región", "resumen": "Convierte las estadísticas públicas de salud de tu región en algo que cualquiera pueda entender, y descubre qué cuentan los números y qué esconden.", "tipo": "Análisis", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Datos abiertos", "Salud pública", "Visualización"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes y estadísticas que publican instituciones de salud y con casos inventados; no hace falta hablar con pacientes reales.", "carreras": ["Estadística", "Ingeniería de Sistemas", "Ingeniería de Software", "Medicina", "Enfermería", "Economía", "Comunicaciones", "Diseño Gráfico"], "problema": ["Los organismos de salud publican cifras sobre atenciones, enfermedades, vacunación o nacimientos, pero casi siempre en tablas largas que casi nadie lee. Eso significa que la información existe pero no llega a las personas ni a quienes deciden.", "Además, las cifras se pueden leer mal: una tendencia puede venir de un cambio en cómo se cuenta, y un promedio puede esconder grandes diferencias entre zonas."], "desarrollar": ["Elige un indicador de salud pública, como atenciones por una enfermedad común, y descarga los datos abiertos de tu región. Limpia las tablas, haz tres gráficos que cuenten una historia, como el cambio en el tiempo o las diferencias entre zonas, y escribe qué se puede y qué no se puede concluir.", "El resultado puede ser un panel o un informe visual de una o dos páginas, con una nota sobre los límites de los datos."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "cruza el indicador con otra variable, como la población o la distancia a un servicio, para ver si aparece una relación."}, {"titulo": "Otro formato", "aporta": "crea un tablero interactivo sencillo para que cualquiera explore los datos."}, {"titulo": "Un paso más", "aporta": "revisa cómo cambian los números cuando se corrigen datos faltantes o atípicos."}], "objetivos": ["Obtener datos abiertos de salud.", "Limpiar y organizar los datos.", "Crear gráficos que cuenten una historia.", "Explicar los límites de lo que se puede concluir."], "habilidades": ["Análisis de datos.", "Visualización de información.", "Lectura crítica de estadísticas.", "Comunicación de resultados."], "herramientas": ["Hoja de cálculo o herramienta de análisis de datos.", "Portales de datos abiertos.", "Herramientas para hacer gráficos."], "lineamientos": ["Usa solo datos públicos y agregados; cita la fuente y la fecha. No interpretes las cifras como diagnósticos ni juzgues a ningún servicio de salud por ellas.", "Aclara qué significan los números y qué no: una correlación no es una causa."], "otroSector": "El mismo análisis sirve para datos de educación, de empleo, de transporte o de seguridad ciudadana."}$f51sld$::jsonb,51),
('un-dia-de-hospital-simulado-cuanta-gente-llega-y-que-cambia-en-un-feriado','salud',array['industria','tecnologia']::text[],'Un día de hospital simulado: ¿cuánta gente llega y qué cambia en un feriado?','Simula con datos inventados cómo llegan los pacientes a un servicio de emergencia a lo largo del día y qué ocurre con la espera cuando hay una demanda inusual.','Simulación','1 a 2 meses',39,array['Simulación','Procesos','Colas']::text[],array['investigar','crear']::text[],'ficticios',NULL,'ingenieria industrial ingenieria de sistemas ingenieria de software estadistica administracion medicina enfermeria economia simulacion de sistemas. teoria de colas basica. analisis de datos. comunicacion de resultados. hoja de calculo o herramienta de simulacion. lenguaje de programacion, con apoyo de una ia o en equipo, si se quiere ir mas lejos. graficos para presentar los resultados.',$f52sld${"id": "un-dia-de-hospital-simulado-cuanta-gente-llega-y-que-cambia-en-un-feriado", "area": "salud", "areas2": ["industria", "tecnologia"], "titulo": "Un día de hospital simulado: ¿cuánta gente llega y qué cambia en un feriado?", "resumen": "Simula con datos inventados cómo llegan los pacientes a un servicio de emergencia a lo largo del día y qué ocurre con la espera cuando hay una demanda inusual.", "tipo": "Simulación", "tiempo": "1 a 2 meses", "horas": 39, "etiquetas": ["Simulación", "Procesos", "Colas"], "intencion": ["investigar", "crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados; no hace falta pedir permiso a nadie ni usar información de pacientes reales.", "carreras": ["Ingeniería Industrial", "Ingeniería de Sistemas", "Ingeniería de Software", "Estadística", "Administración", "Medicina", "Enfermería", "Economía"], "problema": ["Un servicio de emergencia no recibe siempre la misma cantidad de personas: hay horas pico, días de lluvia, feriados largos o épocas de más enfermedades. Cuando llegan más de las que se pueden atender, las esperas crecen y se saturan las camas y el personal.", "Planificar sin ver ese patrón es difícil, y probar cambios en la realidad es costoso y riesgoso. La simulación permite experimentar sin perjudicar a nadie."], "desarrollar": ["Define un servicio ficticio con un número de puestos de atención y personal, y datos inventados de llegadas por hora. Simula un día normal y otro con demanda alta, y mide cuánta gente espera, cuánto tarda y cuándo se llena el servicio.", "Prueba dos o tres cambios, como más personal en horas pico o separar casos leves de graves, y compara los resultados. El resultado puede ser una simulación con conclusiones y recomendaciones."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "incorpora una variable de incertidumbre, como llegadas al azar, y compara varios días simulados."}, {"titulo": "Un paso más", "aporta": "crea una herramienta que permita cambiar los datos y ver el efecto al instante."}, {"titulo": "Otro formato", "aporta": "diseña una presentación para explicar a un público no técnico cómo y por qué se forman las colas."}], "objetivos": ["Definir un modelo simple de un servicio de emergencia.", "Simular días normales y de alta demanda.", "Comparar cambios en la organización.", "Explicar los resultados con claridad."], "habilidades": ["Simulación de sistemas.", "Teoría de colas básica.", "Análisis de datos.", "Comunicación de resultados."], "herramientas": ["Hoja de cálculo o herramienta de simulación.", "Lenguaje de programación, con apoyo de una IA o en equipo, si se quiere ir más lejos.", "Gráficos para presentar los resultados."], "lineamientos": ["Usa datos totalmente inventados y un servicio ficticio: no es una evaluación de ningún hospital ni de ningún equipo de salud. No uses cifras reales para afirmar cómo funciona un establecimiento sin su autorización.", "Aclara que la atención real depende de decisiones clínicas que una simulación no reemplaza."], "otroSector": "El mismo modelo sirve para colas en un banco, una universidad, un aeropuerto, un restaurante o un servicio técnico."}$f52sld$::jsonb,52)
